import{z as r,x as n,o as t,c as s,q as E,j as p,D as e,d as l,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"新凯恩斯菲利普斯曲线","description":"","frontmatter":{"title":"新凯恩斯菲利普斯曲线","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/nk-phillips.md","filePath":"econ/nk-phillips.md","lastUpdated":1791413859000}'),A={name:"econ/nk-phillips.md"};function d(C,a,h,_,c,m){const i=n("Mermaid");return t(),s("div",null,[a[2]||(a[2]=E('<h1 id="新凯恩斯菲利普斯曲线" tabindex="-1">新凯恩斯菲利普斯曲线 <a class="header-anchor" href="#新凯恩斯菲利普斯曲线" aria-label="Permalink to &quot;新凯恩斯菲利普斯曲线&quot;">​</a></h1><div class="epigraph"><p>交错调价一旦写成优化，通胀就不再是外贴的 $\\pi^e$ 加缺口，而是对未来边际成本的贴现；NKPC 是那条一阶条件的对数线性。</p><footer>—— Woodford, Interest and Prices, 2003；对照 Galí, Monetary Policy, Inflation, and the Business Cycle</footer></div><p><a href="/econ/taylor-contracts">上一课</a>（Taylor 交错合同）。已经把粘性钉成 Calvo 抽签与 Rotemberg 二次调价成本，不再从菜单故事起笔。本课的缺口是：把重置价格的一阶条件收成一条可嵌进三方程的通胀方程。后课默认 NKPC 已经成立，只引用 \\(\\kappa\\)、\\(\\beta\\)，不重做交错。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>附加预期的菲利普斯是 \\(\\pi=\\pi^e+\\kappa(u-u^*)\\)。<a href="/econ/new-keynesian">新凯恩斯粘性价格</a>已经预告前瞻形式，但还没有从重置价格推到系数。Calvo 课给出：每期只有 \\(1-\\theta\\) 能改标价，重置者盯的是整段不能再改价的边际成本路径。缺口不是再解释「为什么价格粘」，而是：这条优化如何变成</p> \\[\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\lambda\\widetilde{mc}_t, \\]<p>再把 \\(\\widetilde{mc}\\) 接到产出缺口 \\(\\tilde{y}\\)。没有这一步，利率规则没有供给侧；动态 IS 也没有东西可联立。</p><p><span class="marginnote">\\(\\lambda\\) 随调价频率下降而变小：越少厂商能改价，同样的成本缺口越少进入当期 \\(\\pi\\)。这是粘性的斜率，不是又一次「价格为何不动」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>重置价格是未来名义边际成本的加权贴现，权重含 \\(\\beta\\) 与存活概率 \\(\\theta\\)。围绕零通胀稳态对数线性：当前通胀等于下期通胀预期加上当期真实边际成本缺口——未调价厂商的相对价格被 \\(\\pi\\) 稀释，调价厂商必须把整段预期写进今天的一跳。Galí 的课堂写法把 \\(\\lambda=(1-\\theta)(1-\\beta\\theta)/\\theta\\) 一类接到需求弹性与劳动供给；Woodford 允许不同稳态通胀与指数化，形状同族。</p><p>再把 \\(\\widetilde{mc}\\) 写成 \\(\\tilde{y}\\) 的单调函数（劳动市场出清、生产函数），得到标准 NKPC</p> \\[\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t. \\]<p>\\(\\kappa\\) 随 \\(\\theta\\) 上升而下降。Rotemberg 二次成本对数线性后得到同形方程，\\(\\kappa\\) 的微观不同、宏观用法相同——上一课已经并列过两种粘性，本课只取「同形」。</p><p><span class="marginnote">数字实例：取季度 \\(\\beta=0.99\\)、\\(\\kappa=(1-\\theta)(1-\\beta\\theta)/\\theta\\)。调价快（\\(\\theta=0.25\\)）时 \\(\\kappa\\approx 2.26\\)；价格很粘（\\(\\theta=0.75\\)）时 \\(\\kappa\\approx 0.09\\)——同样的产出缺口，通胀反应差出二十多倍。粘性不是口号，全写在这个斜率里。</span></p>',14)),(t(),p(o,null,{default:e(()=>[B(i,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22Calvo%20%E9%87%8D%E7%BD%AE%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20NKPC%5B%22%CF%80%20%3D%20%CE%B2E%CF%80%20%2B%20%CE%BB%20mc%CC%83%22%5D%0A%20%20MC%5B%22%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20NKPC%0A%20%20NKPC%20--%3E%20GAP%5B%22%E6%8E%A5%E5%88%B0%20%E1%BB%B9%EF%BC%9A%CE%BA%20%E1%BB%B9%22%5D%0A%20%20RULE%5B%22%E5%90%8E%E8%AF%BE%E5%88%A9%E7%8E%87%E8%A7%84%E5%88%99%22%5D%20--%3E%20EXP%5B%22E%CF%80%20%E5%86%85%E7%94%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="与附加预期-phillips-的差" tabindex="-1">与附加预期 Phillips 的差 <a class="header-anchor" href="#与附加预期-phillips-的差" aria-label="Permalink to &quot;与附加预期 Phillips 的差&quot;">​</a></h3><p>Friedman–Phelps 的 \\(\\pi^e\\) 可以是适应性；NKPC 的 \\(\\mathbb{E}_t\\pi_{t+1}\\) 是模型给出的条件期望。截距随规则而动，正是<a href="/econ/lucas-critique">卢卡斯批判</a>要的结构：改 \\(g\\)，连 Phillips 一起重解。混合 NKPC 加 \\(\\pi_{t-1}\\) 是经验修补，不是本课的一阶条件。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是前瞻贴现。今天的 \\(\\pi\\) 已经包含 \\(\\mathbb{E}\\pi_{t+1}\\)：若规则让公众相信缺口将被关掉，当前通胀立刻下降，不必先走过一整串失业。长期 \\(\\tilde{y}=0\\)、\\(\\pi\\) 由名义锚决定，与自然率兼容。成本推动（markup 冲击）作为残差进入，使 \\(\\pi\\) 与 \\(\\tilde{y}\\) 可以同向——<a href="/econ/divine-coincidence">神圣巧合</a>会问这是否破坏「稳通胀即稳缺口」。</p>',4)),(t(),p(o,null,{default:e(()=>[B(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%A4%AE%E8%A1%8C%E5%AE%A3%E5%B8%83%EF%BC%9A%E5%B0%86%E6%94%B6%E7%B4%A7%E7%9B%B4%E8%87%B3%E9%80%9A%E8%83%80%E5%9B%9E%E5%88%B0%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20BEL%7B%22%E5%85%AC%E4%BC%97%E7%9B%B8%E4%BF%A1%E8%BF%99%E4%B8%AA%E6%89%BF%E8%AF%BA%E5%90%97%EF%BC%9F%22%7D%0A%20%20BEL%20--%3E%7C%22%E4%BF%A1%22%7C%20EP%5B%22%E9%A2%84%E6%9C%9F%20E%CF%80(t%2B1)%20%E7%AB%8B%E5%88%BB%E4%B8%8B%E8%B0%83%22%5D%0A%20%20EP%20--%3E%20NOW%5B%22%E5%BD%93%E6%9C%9F%20%CF%80%20%E7%9A%84%20%CE%B2%C2%B7E%CF%80%20%E9%A1%B9%E7%AB%8B%E5%88%BB%E5%8F%98%E5%B0%8F%22%5D%0A%20%20NOW%20--%3E%20FAST%5B%22%E5%BD%93%E5%89%8D%E9%80%9A%E8%83%80%E5%8D%B3%E6%97%B6%E5%9B%9E%E8%90%BD%EF%BC%8C%E5%A4%B1%E4%B8%9A%E4%BB%A3%E4%BB%B7%E5%B0%8F%22%5D%0A%20%20BEL%20--%3E%7C%22%E4%B8%8D%E4%BF%A1%22%7C%20GAP%5B%22%E9%A2%84%E6%9C%9F%E4%B8%8D%E5%8A%A8%EF%BC%8C%E5%8F%AA%E8%83%BD%E5%8E%8B%E7%9C%9F%E5%AE%9E%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20GAP%20--%3E%20SLOW%5B%22%E9%80%9A%E8%83%80%E7%BC%93%E6%85%A2%E4%B8%8B%E8%A1%8C%EF%BC%8C%E8%A6%81%E7%86%AC%E4%B8%80%E6%95%B4%E6%AE%B5%E9%AB%98%E5%A4%B1%E4%B8%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">直觉类比：NKPC 像一台「预期定价投票机」。今天的通胀是全体重置厂商对未来通胀预期的加权贴现，加上当期缺口的分量——预期一变，票箱立刻变。「宣布即压通胀」与「必须先熬衰退」两条路的分岔口就在这里。</span></p><p>灵活价格极限 \\(\\theta\\to 0\\) 或 Rotemberg 成本趋于零，\\(\\kappa\\to\\infty\\)，缺口被压掉，货币中性在周期频率上恢复，接到 <a href="/econ/rbc-contrast">RBC 对照</a>。动态 IS 从后课接过需求侧：没有 NKPC，利率规则只有欧拉，没有通胀。三方程必须先有这一条供给。索引化（过去通胀进入未调价合同）会加进滞后项，那是对 Calvo 一阶条件的修改，不是本课的基准。</p><p><span class="marginnote">工资粘性会再写一条工资菲利普斯。本课只做价格 NKPC。两套粘性并存时，\\(\\kappa\\) 的解释变，方程形状仍前瞻。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 \\(\\kappa\\)，不把 1958 年 Phillips 的统计替换再讲一遍。量化栏的限价不是宏观 Calvo。指数化、正稳态通胀会改线性化细节，不取消前瞻结构。</p><p><span class="marginnote">常见误区：把 \\(\\kappa\\) 读成旧菲利普斯回归里「通胀对失业的敏感度」。\\(\\kappa\\) 是重置概率的函数，出自优化的一阶条件；它的变化不是重新拟合一条回归线的事，而是调价技术、指数化或政策规则变化的结构后果。</span></p><p>后课默认：供给侧是 \\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t\\)。后课把欧拉对数线性成与它对偶的动态 IS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NKPC 是重置价格一阶条件的对数线性，不是外贴 \\(\\pi^e\\)。</li><li>\\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t\\)；\\(\\kappa\\) 随调价频率下降。</li><li>预期是结构的一部分，规则一变截距跟着变。</li><li>Calvo 与 Rotemberg 宏观同形；本课不重写粘性故事。</li><li>灵活价格极限 \\(\\kappa\\to\\infty\\)，缺口被压掉，接到 RBC。</li><li>出处：Woodford, <em>Interest and Prices</em>；Galí 的 NK 课本推导。</li></ul>',9))])}const k=r(A,[["render",d]]);export{P as __pageData,k as default};
